const fs = require("fs");
const rev = JSON.parse(fs.readFileSync("outputs/pr_review.json", "utf8"));
const diff = fs.readFileSync("/tmp/full_diff.txt", "utf8");
// build set of added lines per file from the diff
const added = {};
let cur = null;
for (const l of diff.split("\n")) {
  if (l.startsWith("diff --git")) { cur = l.split(" b/")[1]; continue; }
  if (l.startsWith("+") && !l.startsWith("+++")) (added[cur] = added[cur] || []).push(l.slice(1));
}
let fail = 0;
for (const c of rev.inlineComments) {
  const inDiff = (added[c.path] || []).includes("__LINENO__"); // placeholder
  // line numbers: check the file content at that line matches an added line
  const content = fs.readFileSync(c.path, "utf8").split("\n");
  const lineText = content[c.line - 1];
  const present = (added[c.path] || []).includes(lineText);
  console.log(`${present ? "OK " : "BAD"} ${c.path}:${c.line} severity=${c.severity} :: ${JSON.stringify((lineText||"").slice(0,70))}`);
  if (!present) fail++;
}
// cross-checks per verdict rules
console.log("recommendation:", rev.recommendation, "| blocking:", rev.issueCounts.blocking);
if (rev.recommendation === "REQUEST_CHANGES" && rev.issueCounts.blocking < 1) { console.log("BAD: REQUEST_CHANGES with blocking 0"); fail++; }
const files = ["outputs/pr_review_general.md"].concat(rev.inlineComments.map(c => c.comment));
for (const f of files) console.log(fs.existsSync(f) ? "OK exists: " + f : "BAD missing: " + f);
console.log(fail === 0 ? "ALL_CHECKS_PASS" : "CHECKS_FAILED=" + fail);
'; echo "---"; wc -l outputs/pr_review_general.md outputs/pr_review.json outputs/pr_review_comments/*.md

