const fs = require("fs");
const rev = JSON.parse(fs.readFileSync("outputs/pr_review.json", "utf8"));
const diff = fs.readFileSync("/tmp/full_diff2.txt", "utf8");
const added = {}; let cur = null;
for (const l of diff.split("\n")) {
  if (l.startsWith("diff --git")) { cur = l.split(" b/")[1]; continue; }
  if (l.startsWith("+") && !l.startsWith("+++")) (added[cur] = added[cur] || []).push(l.slice(1));
}
let fail = 0;
for (const c of rev.inlineComments) {
  const lineText = fs.readFileSync(c.path, "utf8").split("\n")[c.line - 1];
  const present = (added[c.path] || []).includes(lineText);
  console.log(`${present ? "OK " : "BAD"} ${c.path}:${c.line} ${c.severity}`);
  if (!present) fail++;
}
// verdict-rule cross-checks
if (rev.recommendation === "APPROVE" && rev.issueCounts.blocking !== 0) { console.log("BAD: APPROVE with blocking>0"); fail++; }
for (const c of rev.inlineComments) {
  const body = fs.readFileSync(c.comment, "utf8");
  if (body.includes("🚨") || c.severity === "BLOCKING") { console.log("BAD: 🚨/BLOCKING marker in APPROVE comment " + c.comment); fail++; }
}
for (const f of ["outputs/pr_review_general.md"].concat(rev.inlineComments.map(c => c.comment)))
  if (!fs.existsSync(f)) { console.log("BAD missing " + f); fail++; }
for (const id of rev.resolvedThreadIds || []) {
  const raw = JSON.parse(fs.readFileSync("input/pr-1158/pr_discussions_raw.json", "utf8"));
  if (!raw.threads.some(t => t.threadId === id)) { console.log("BAD unknown threadId " + id); fail++; }
}
console.log("resolvedThreadIds:", (rev.resolvedThreadIds||[]).length, "| recommendation:", rev.recommendation, "| counts:", JSON.stringify(rev.issueCounts));
console.log(fail === 0 ? "ALL_CHECKS_PASS" : "CHECKS_FAILED=" + fail);
'; wc -l outputs/pr_review_general.md

